CREATE TABLE `resource_grant_actions` (`grant_id` CHAR(36) CHARACTER SET ascii NOT NULL,`capability_code` VARCHAR(80) CHARACTER SET ascii NOT NULL,`created_at` DATETIME(3) NOT NULL,PRIMARY KEY(`grant_id`,`capability_code`),KEY `idx_resource_grant_actions_capability`(`capability_code`,`grant_id`),CONSTRAINT `fk_resource_grant_actions_grant` FOREIGN KEY(`grant_id`) REFERENCES `resource_grants`(`id`) ON DELETE CASCADE,CONSTRAINT `fk_resource_grant_actions_capability` FOREIGN KEY(`capability_code`) REFERENCES `capabilities`(`code`) ON DELETE RESTRICT) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
